    18	function mapRowToBalance(row: BalanceRow): Balance {
    19	  return {
    20	    id: row.id,
    21	    employeeId: row.employee_id,
    22	    leaveType: row.leave_type,
    23	    totalEntitlement: row.total_entitlement,
    24	    usedDays: row.used_days,
