    33	const COLUMN_MAP: Record<string, string> = {
    34	  employeeId: 'employee_id',
    35	  leaveType: 'leave_type',
    36	  totalEntitlement: 'total_entitlement',
    37	  usedDays: 'used_days',
    38	  remainingDays: 'remaining_days',
    39	  fiscalYear: 'fiscal_year',
