    77	  async create(
    78	    balance: Omit<Balance, 'id' | 'createdAt' | 'updatedAt'>,
    79	  ): Promise<Balance> {
    80	    const result = await pool.query<BalanceRow>(
    81	      `INSERT INTO balances (
    82	        employee_id, leave_type, total_entitlement,
    83	        used_days, remaining_days, fiscal_year, status
    84	      ) VALUES ($1, $2, $3, $4, $5, $6, $7)
    85	      RETURNING *`,
    86	      [
    87	        balance.employeeId,
    88	        balance.leaveType,
    89	        balance.totalEntitlement,
    90	        balance.usedDays,
    91	        balance.remainingDays,
    92	        balance.fiscalYear,
    93	        balance.status,
    94	      ],
    95	    );
