    99	  async update(
   100	    id: string,
   101	    data: Partial<Balance>,
   102	  ): Promise<Balance | null> {
   103	    const keys = Object.keys(data).filter(
   104	      (k) =>
   105	        data[k as keyof typeof data] !== undefined &&
   106	        COLUMN_MAP[k] !== undefined,
   107	    );
   108	
   109	    if (keys.length === 0) {
   110	      const existing = await this.findById(id);
   111	      return existing;
   112	    }
   113	
   114	    const setClauses = keys.map(
   115	      (key, index) => `${COLUMN_MAP[key]} = $${index + 2}`,
   116	    );
   117	    const values = keys.map((key) => data[key as keyof typeof data]);
   118	
   119	    const result = await pool.query<BalanceRow>(
   120	      `UPDATE balances SET ${setClauses.join(', ')}, updated_at = NOW() WHERE id = $1 RETURNING *`,
   121	      [id, ...values],
   122	    );
   123	
   124	    if (result.rows.length === 0) {
   125	      return null;
   126	    }
   127	    return mapRowToBalance(result.rows[0]);
